DO $$ DECLARE f record; def text; BEGIN FOR f IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('rider_delivery_action','resolve_rider_return','review_rider_earning') LOOP def:=pg_get_functiondef(f.oid); def:=replace(def,'''delivery_exception''','''status'''); def:=replace(def,'''return_confirmed''','''status'''); def:=replace(def,'''earning_reviewed''','''status'''); def:=replace(def,'''/order/''||_order_id','''/order-tracking/''||_order_id||CASE WHEN _kind=''food'' THEN '''' WHEN _kind=''grocery_list'' THEN ''?type=grocery_list'' ELSE ''?type=grocery'' END'); EXECUTE def; END LOOP; END $$;